30	    //  e.g., `id[dimIdx]` is `0` or `1` or `2` or `3` if there are at most `4` leaves in the tree.
31	    // For a `MatrixDimensionLevelInfo`:
32	    //  it is `setDimXYValue(new Point(), dimIdx, 0, level - _levels.length)`
33	    //  e.g., `id[1 - dimIdx]` is `-3` or `-2` or `-1` if the tree has `3` levels.
34	    // If negative, locate to corner cells; otherwise, locate to body cells.
35	    id: Point;
36	    // By pixel. Computed left-top x (for x dimension) or y (for y dimension).
37	    // Used to locate.
38	    xy: number;
39	    // By pixel. Computed height (for x dimension) or width (for y dimension).
40	    // Used to locate.
41	    wh: number;
42	    dim: MatrixDim;
