274	    private _initBySeriesData() {
275	        const self = this;
276	        self._leavesCount = 0;
277	        self._levels = [{
278	            type: MatrixCellLayoutInfoType.level,
279	            xy: NaN, wh: NaN, option: null, id: new Point(), dim: self
280	        }];
281	        self._initLevelIdOptions();
282	
283	        const ordinalMeta = self._ordinalMeta = new OrdinalMeta({
284	            needCollect: true,
285	            deduplication: true,
286	            onCollect: (value: unknown, ordinalNumber: number): void => {
287	                const cell = self._cells[ordinalNumber] = {
288	                    type: MatrixCellLayoutInfoType.leaf,
289	                    ordinal: ordinalNumber,
290	                    level: 0,
291	                    firstLeafLocator: ordinalNumber,
292	                    id: new Point(), // Set it in `_initCellsId`.
293	                    span: setDimXYValue(new Point(), self.dimIdx, 1, 1),
294	                    // Theoretically `value` is from `dataset` or `series.data`, so it may be any type.
295	                    // Do not restrict this case for user's convenience, and here simply convert it to
296	                    // string for display.
297	                    option: {value: value + ''},
298	                    xy: NaN,
299	                    wh: NaN,
300	                    dim: self,
301	                    rect: createNaNRectLike(),
302	                };
303	                self._leavesCount++;
304	                self._setCellId(cell);
305	            },
306	        });
