340	    /**
341	     * Iterate leaves (they are layout units) if dimIdx === this.dimIdx.
342	     * Iterate levels if dimIdx !== this.dimIdx.
343	     */
344	    resetLayoutIterator(
345	        it: ListIterator<MatrixCellLayoutInfo> | NullUndefined,
346	        dimIdx: number,
347	        startLocator?: MatrixXYLocator | NullUndefined,
348	        count?: number | NullUndefined,
349	    ): ListIterator<MatrixCellLayoutInfo> {
350	        it = it || new ListIterator<MatrixCellLayoutInfo>();
351	        if (dimIdx === this.dimIdx) {
352	            const len = this._leavesCount;
353	            const startIdx = startLocator != null ? Math.max(0, startLocator) : 0;
354	            count = count != null ? Math.min(count, len) : len;
355	            it.reset(this._cells, startIdx, startIdx + count);
356	        }
357	        else {
358	            const len = this._levels.length;
359	            // Corner locator is from `-this._levels.length` to `-1`.
360	            const startIdx = startLocator != null ? Math.max(0, startLocator + len) : 0;
361	            count = count != null ? Math.min(count, len) : len;
362	            it.reset(this._levels, startIdx, startIdx + count);
363	        }
364	        return it;
365	    }
