54	    render(matrixModel: MatrixModel) {
55	
56	        this.group.removeAll();
57	
58	        const group = this.group;
59	        const coordSys = matrixModel.coordinateSystem;
60	        const rect = coordSys.getRect();
61	        const xDimModel = matrixModel.getDimensionModel('x');
62	        const yDimModel = matrixModel.getDimensionModel('y');
63	        const xDim = xDimModel.dim;
64	        const yDim = yDimModel.dim;
65	
66	        // PENDING:
67	        //  reuse the existing text and rect elements for performance?
68	
69	        renderDimensionCells(
70	            group,
71	            matrixModel
72	        );
73	
74	        createBodyAndCorner(
75	            group,
76	            matrixModel,
77	            xDim,
78	            yDim
79	        );
80	
81	        const borderZ2Option = matrixModel.getShallow('borderZ2', true);
82	        const outerBorderZ2 = retrieve2(borderZ2Option, Z2_OUTER_BORDER);
83	        const dividerLineZ2 = outerBorderZ2 - 1;
84	
85	        // Outer border and overall background. Use separate elements because of z-order:
86	        // The overall background should appear below any other elements.
87	        // But in most cases, the outer border and the divider line should be above the normal cell borders -
88	        // especially when cell borders have different colors. But users may highlight some specific cells by
89	        // overstirking their border, in which case it should be above the outer border.
90	        const bgStyle = matrixModel.getModel('backgroundStyle').getItemStyle(
91	            ['borderWidth']
92	        );
93	        bgStyle.lineWidth = 0;
94	        const borderStyle = matrixModel.getModel('backgroundStyle').getItemStyle(
95	            ['color', 'decal', 'shadowColor', 'shadowBlur', 'shadowOffsetX', 'shadowOffsetY']
96	        );
97	        borderStyle.fill = 'none';
98	        const bgRect = createMatrixRect(rect.clone(), bgStyle, Z2_BACKGROUND);
99	        const borderRect = createMatrixRect(rect.clone(), borderStyle, outerBorderZ2);
100	        bgRect.silent = true;
101	        borderRect.silent = true;
102	        group.add(bgRect);
103	        group.add(borderRect);
104	
105	        // Header split line.
106	        const xDimCell0 = xDim.getUnitLayoutInfo(0, 0);
107	        const yDimCell0 = yDim.getUnitLayoutInfo(1, 0);
108	        if (xDimCell0 && yDimCell0) {
109	            if (xDim.shouldShow()) {
110	                group.add(createMatrixLine(
111	                    {
112	                        x1: rect.x,
113	                        y1: yDimCell0.xy,
114	                        x2: rect.x + rect.width,
115	                        y2: yDimCell0.xy,
116	                    },
117	                    xDimModel.getModel('dividerLineStyle').getLineStyle(),
118	                    dividerLineZ2,
119	                ));
120	            }
121	            if (yDim.shouldShow()) {
122	                group.add(createMatrixLine(
123	                    {
124	                        x1: xDimCell0.xy,
125	                        y1: rect.y,
126	                        x2: xDimCell0.xy,
127	                        y2: rect.y + rect.height,
128	                    },
129	                    yDimModel.getModel('dividerLineStyle').getLineStyle(),
130	                    dividerLineZ2,
131	                ));
132	            }
133	        }
134	    }
