80	export function resetXYLocatorRange(out: unknown[] | NullUndefined): MatrixXYLocatorRange {
81	    const rg = (out || []) as MatrixXYLocatorRange;
82	    rg[0] = rg[0] || [];
83	    rg[1] = rg[1] || [];
84	    rg[0][0] = rg[0][1] = rg[1][0] = rg[1][1] = NaN;
