202	// `locatorRange` will be expanded (modified) if an intersection is encountered.
203	export function resolveXYLocatorRangeByCellMerge(
204	    inOutLocatorRange: MatrixXYLocatorRange,
205	    // Item indices coorespond to mergeDefList (len: mergeDefListTravelLen).
206	    // Indicating whether each item has be merged into the `locatorRange`
207	    outMergedMarkList: boolean[] | NullUndefined,
208	    mergeDefList: {
209	        locatorRange: MatrixXYLocatorRange | NullUndefined;
210	        cellMergeOwner: boolean;
211	    }[],
212	    mergeDefListTravelLen: number,
213	): void {
214	    outMergedMarkList = outMergedMarkList || _tmpOutMergedMarkList;
215	    for (let idx = 0; idx < mergeDefListTravelLen; idx++) {
216	        outMergedMarkList[idx] = false;
217	    }
218	    // In most case, cell merging definition list length is smaller than the range extent,
219	    // therefore, to detection intersection, travelling cell merging definition list is probably
220	    // performant than traveling the four edges of the rect formed by the locator range.
221	    while (true) {
222	        let expanded = false;
223	        for (let idx = 0; idx < mergeDefListTravelLen; idx++) {
224	            const mergeDef = mergeDefList[idx];
225	            if (!outMergedMarkList[idx]
226	                && mergeDef.cellMergeOwner
227	                && expandXYLocatorRangeIfIntersect(inOutLocatorRange, mergeDef.locatorRange)
228	            ) {
229	                outMergedMarkList[idx] = true;
230	                expanded = true;
231	            }
232	        }
233	        if (!expanded) {
234	            break;
235	        }
236	    }
237	}
238	const _tmpOutMergedMarkList: boolean[] = [];
