import { createChart, removeChart } from '../../test/ut/core/utHelper';

describe('matrix-dimension-length', function () {

    it('matrix.x/y.length creates a headless matrix', function () {
        const chart = createChart();
        chart.setOption({
            matrix: {
                x: {length: 4},
                y: {length: 3}
            },
            series: {
                type: 'scatter',
                coordinateSystem: 'matrix',
                data: [[0, 0, 10], [3, 2, 20]]
            }
        });

        // In-boundary locators can be converted.
        const px00 = chart.convertToPixel({matrixIndex: 0}, [0, 0]);
        expect(px00[0]).not.toBeNaN();
        expect(px00[1]).not.toBeNaN();
        const px32 = chart.convertToPixel({matrixIndex: 0}, [3, 2]);
        expect(px32[0]).not.toBeNaN();
        expect(px32[1]).not.toBeNaN();

        // Out-of-boundary locators result in NaN (no clamp by default).
        const pxOut = chart.convertToPixel({matrixIndex: 0}, [4, 0]);
        expect(pxOut[0]).toBeNaN();

        // Generated cells can be queried by generated ordinal values.
        const pxByVal = chart.convertToPixel({matrixIndex: 0}, ['X1', 'Y1']);
        const pxByIdx = chart.convertToPixel({matrixIndex: 0}, [1, 1]);
        expect(pxByVal[0]).toEqual(pxByIdx[0]);
        expect(pxByVal[1]).toEqual(pxByIdx[1]);

        removeChart(chart);
    });

    it('array-based x/y.data keeps working and wins over length', function () {
        const chart = createChart();
        chart.setOption({
            matrix: {
                x: {data: ['a', 'b'], length: 5},
                y: {data: ['c', 'd', 'e']}
            },
            series: {
                type: 'scatter',
                coordinateSystem: 'matrix',
                data: [['a', 'c', 10], ['b', 'e', 20]]
            }
        });

        const px = chart.convertToPixel({matrixIndex: 0}, ['b', 'e']);
        expect(px[0]).not.toBeNaN();
        expect(px[1]).not.toBeNaN();
        // `length: 5` must be ignored since `data` is specified: index 2 is out of x boundary.
        const pxOut = chart.convertToPixel({matrixIndex: 0}, [2, 0]);
        expect(pxOut[0]).toBeNaN();

        removeChart(chart);
    });
});

